import { WORKSPACES, PEOPLE, FACTS, parseEntries, rollIndex, rosterStats, pendingPeople, commitmentStats, projectedCoverage, shouldAllowOverride, dateLabel, triviaQuestion } from './lib.js';
import { DEMO_ACTORS, canManage, isInScope, scopedPeople, canMarkPerson, canReviewRequest, canReassignPerson, countQueue, validateProfile, WORKSPACE_TEAMS } from './access.js';
import { PORTRAITS } from './assets.js';

const $ = (selector,root=document) => root.querySelector(selector);
const all = (selector,root=document) => [...root.querySelectorAll(selector)];
const esc = v => String(v??'').replace(/[&<>"']/g, x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const iconPaths = {
  today:'<path d="M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z"/><path d="m9 16 2 2 4-4"/>',
  attendance:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',
  commitments:'<path d="M3 12a9 9 0 1 0 9-9M3 4v8h8"/><path d="m10 12 2 2 4-4"/>',
  reports:'<path d="M4 20V11M10 20V4M16 20v-7M22 20V8"/>',
  team:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M18 8a3 3 0 0 1 0 6M17 17a4 4 0 0 1 4 4"/>',
  updates:'<path d="m3 11 15-7v16L3 13v-2ZM7 14l2 6h3"/>',
  manager:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M8 9h8M8 13h5"/>',
  profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
  play:'<path d="M4 12h16M12 4v16M5.5 5.5l13 13M18.5 5.5l-13 13"/><circle cx="12" cy="12" r="10"/>',
};
const navItems=[['today','Today'],['attendance','Attendance'],['commitments','Commitments'],['reports','Reports'],['manager','Manager'],['team','Team'],['updates','Updates'],['play','Play'],['profile','Profile']];
const ic=k=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${iconPaths[k]}</svg>`;
const storeKey='qswipe-demo-v1';
function load(){try{const data=JSON.parse(localStorage.getItem(storeKey));return data && typeof data==='object'?data:{};}catch{return {};}}
const persisted=load();
const state={
  workspace:'bpo', actorId:'lead', role:'manager', page:'today', game:'wheel', gameText:'', entriesHidden:false, gameWinner:null, gameRunning:false, wheelRotation:0,
  cardRevealed:-1, cardOrder:[], trivia:null, triviaCategory:'Mixed', triviaLength:5, date:new Date().toLocaleDateString('en-CA'),
  attendance:persisted.attendance||{}, commitments:persisted.commitments||{}, announcements:persisted.announcements||[], acked:persisted.acked||{},
  profiles:persisted.profiles||{}, assignments:persisted.assignments||{}, exceptions:persisted.exceptions||{},
  requests:Array.isArray(persisted.requests)?persisted.requests:[
    {id:'sample-req-1',workspace:'bpo',date:new Date().toLocaleDateString('en-CA'),personId:'p2',type:'correction',desiredStatus:'present',note:'Missed my check-in while assisting a customer.',status:'pending',createdAt:new Date().toISOString()},
    {id:'sample-req-2',workspace:'bpo',date:new Date().toLocaleDateString('en-CA'),personId:'p6',type:'leave',desiredStatus:'',note:'Requesting leave review for this shift.',status:'pending',createdAt:new Date().toISOString()}
  ],
  audit:Array.isArray(persisted.audit)?persisted.audit:[], targets:persisted.targets||{},
  managerTeamFilter:'all', avatarUrls:{}, lastAction:null, queueOffset:0
};
let toastTimer=null,gameTimer=null;
function save(){
  try{localStorage.setItem(storeKey,JSON.stringify({attendance:state.attendance,commitments:state.commitments,announcements:state.announcements,acked:state.acked,profiles:state.profiles,assignments:state.assignments,exceptions:state.exceptions,requests:state.requests,audit:state.audit,targets:state.targets}));}
  catch{notify('Your browser could not save the demo state.');}
}
function ws(){return WORKSPACES[state.workspace];}
function currentKey(){return `${state.workspace}|${state.date}`;}
function currentAttendance(){return state.attendance[currentKey()]||{};}
function currentCommitments(){return state.commitments[currentKey()]||{};}
function actor(){
  const base=DEMO_ACTORS[state.actorId]||DEMO_ACTORS.member;
  const override=state.profiles[state.actorId]||{};
  return {...base,team:base.level<=1?WORKSPACE_TEAMS[state.workspace][0]:base.team,name:override.name||base.name,title:override.title||base.title,about:override.about||''};
}
function isManager(){return actor().level>=1;}
function allWorkspacePeople(){return PEOPLE.map(p=>{
  const ownProfile=p.id==='p1'?(state.profiles.member||{}):{};
  return {...p, name:ownProfile.name||p.name, position:p.id==='p1'&&ownProfile.title?ownProfile.title:(state.workspace==='bpo'?p.position:state.workspace==='school'?'Learner':state.workspace==='government'?'Public Service Staff':'Creative Associate'),team:state.assignments[state.workspace]?.[p.id]||WORKSPACE_TEAMS[state.workspace][p.team==='Nova'?1:0]};
});}
function people(){return scopedPeople(actor(),allWorkspacePeople());}
/** Carry the manager's team/class filter into the swipe queue, without widening scope. */
function attendancePeople(){const scoped=people();return isManager()&&state.managerTeamFilter!=='all'?scoped.filter(p=>p.team===state.managerTeamFilter):scoped;}
function currentExceptions(){return state.exceptions[currentKey()]||{};}
function canSeeAttendance(person){return isInScope(actor(),person);}
function avatarSource(person){return person.id==='p1'&&state.avatarUrls.member?state.avatarUrls.member:PORTRAITS[person.portrait];}
function auditAction(action,personId,detail){state.audit.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),workspace:state.workspace,actor:actor().name,action,personId,detail:String(detail||'').slice(0,160)});state.audit=state.audit.slice(0,100);}
function photo(p){return `<img class="avatar" src="${esc(avatarSource(p))}" alt="Portrait of ${esc(p.name)}">`;}
function notify(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2700);}
function clearGameTimer(){if(gameTimer)clearTimeout(gameTimer);gameTimer=null;state.gameRunning=false;}
function resetGameResult(){clearGameTimer();state.gameWinner=null;state.wheelRotation=0;state.cardRevealed=-1;state.cardOrder=[];}
function setupNav(){
  const visible=navItems.filter(([key])=>key!=='manager'||isManager());
  for(const id of ['#desktop-nav','#mobile-nav'])$(id).innerHTML=visible.map(([key,label])=>`<button class="nav-button" type="button" data-page="${key}" aria-current="${state.page===key?'page':'false'}">${ic(key)}<span>${label}</span></button>`).join('');
}
function render(){
  if(state.page==='manager'&&!isManager())state.page='today';
  state.role=isManager()?'manager':'member';
  setupNav();$('#workspace').value=state.workspace;$('#role').value=state.actorId;
  const name=navItems.find(x=>x[0]===state.page)?.[1]||'Today';
  $('#context-label').textContent=ws().industry.toUpperCase()+' WORKSPACE';$('#context-title').textContent=name;
  const a=actor(), avatar=$('#profile-shortcut');if(avatar){
    avatar.innerHTML=state.avatarUrls[state.actorId]?`<img src="${esc(state.avatarUrls[state.actorId])}" alt="">`:esc(a.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase());
    avatar.setAttribute('aria-label',`Open ${a.name}'s profile`);
  }
  let body='';switch(state.page){case 'today':body=todayView();break;case 'attendance':body=attendanceView();break;case 'commitments':body=commitmentsView();break;case 'reports':body=reportsView();break;case 'manager':body=managerView();break;case 'team':body=teamView();break;case 'updates':body=updatesView();break;case 'play':body=gamesView();break;case 'profile':body=profileView();break;}
  $('#main').innerHTML=`<div class="enter">${body}</div>`;bindView();
}
function head(title,subtitle,actions=''){return `<div class="page-head"><div><p class="eyebrow">${esc(ws().industry.toUpperCase())} / ${esc(ws().name.toUpperCase())}</p><h1>${esc(title)}</h1><p class="muted">${esc(subtitle)}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
function stat(label,value,foot=''){return `<div class="stat"><small>${esc(label)}</small><strong>${esc(value)}</strong>${foot?`<em>${esc(foot)}</em>`:''}</div>`;}
function portraitCard(p,mode){return `<article class="portrait-card" id="swipe-card" tabindex="0" role="group" aria-label="${esc(p.name)}, ${esc(p.position)}. Swipe left for absent or right for present."><div class="portrait-image"><img src="${esc(avatarSource(p))}" alt="Portrait of ${esc(p.name)}"></div><div class="portrait-content"><span class="eyebrow">${mode==='manager'?'VERIFY ATTENDANCE':'YOUR CHECK-IN'}</span><h2>${esc(p.name)}</h2><div class="portrait-meta">${esc(p.position)} · ${esc(ws().groupLabel)} ${esc(p.team)}</div><div class="portrait-bottom"><span class="pill">${esc(dateLabel(state.date))}</span><span class="pill">${esc(ws().shift)}</span></div></div></article>`;}
function swipeControls(p){return `<div class="swipe-hints"><span class="left">← Absent</span><span class="right">Present →</span></div>${portraitCard(p,state.role)}<div class="card-actions"><button class="button danger" id="mark-absent" type="button">← Absent</button><button class="button success" id="mark-present" type="button">Present →</button></div><div class="action-foot"><button class="button ghost" id="skip-card" type="button">Skip</button><button class="button ghost" id="undo-swipe" type="button" ${!canUndo()?'disabled':''}>Undo last swipe</button></div>`;}
function canUndo(){return Boolean(state.lastAction&&state.lastAction.key===currentKey()&&Date.now()-state.lastAction.at<10000);}
function todayView(){const roster=people(),stats=rosterStats(roster,currentAttendance());const leave=roster.filter(p=>currentExceptions()[p.id]).length;return `${head('Good day, team.','Attendance, commitments and team operations in one place.',`<span class="pill green">${esc(dateLabel(state.date))}</span>`)}<section class="panel hero"><div><span class="eyebrow">TODAY AT A GLANCE</span><h2>Every presence counts.</h2><p class="small-note">${isManager()?'Verify missing check-ins and resolve team requests.':'Check in, plan your shift and review your profile.'}</p></div><img src="./brand.svg" alt=""></section><div class="stats">${stat('Roster in scope',stats.scheduled)}${stat('Present',stats.present)}${stat('Absent',stats.absent)}${stat('Unmarked',Math.max(0,stats.pending-leave),leave?`${leave} approved leave`:'Awaiting check-in')}</div><div class="grid two"><section class="panel"><div class="panel-header"><h2>${isManager()?'Manager quick actions':'Attendance quick action'}</h2><span class="pill">Demo</span></div>${isManager()?`<p class="small-note">${esc(actor().title)} · ${actor().level===1?'Team '+esc(actor().team):'All teams'}.</p><div class="divider"></div><div class="stack"><button class="button primary full" id="go-attendance" type="button">Open scoped swipe queue</button><button class="button full" type="button" data-page="manager">Manager workspace and approvals</button></div>`:`<div class="swipe-area">${currentAttendance()[roster[0]?.id]?`<div class="status-block"><strong>Attendance recorded: ${esc(currentAttendance()[roster[0].id])}</strong><p>Request a correction from Profile when needed.</p></div><button class="button" type="button" data-page="profile">Open profile</button>`:roster[0]?swipeControls(roster[0]):'<div class="empty">No assigned shift</div>'}</div>`}</section><section class="panel"><div class="panel-header"><h2>Upcoming commitment</h2><span class="pill amber">Next shift</span></div><p class="small-note">${isManager()?'View the staffing forecast and follow up on unavailable team members.':'Let your team know whether you can attend.'}</p><div class="divider"></div>${isManager()?`<button class="button primary full" type="button" data-page="commitments">See team commitments</button>`:`<div class="stack"><button class="button success full" data-commit="confirmed">I can attend</button><button class="button full" data-commit="risk">I’m at risk</button><button class="button danger full" data-commit="unavailable">Unavailable</button></div>`}</section></div>`;}
function attendanceView(){
 const p=attendancePeople(),records=currentAttendance(),ex=currentExceptions(),queued=countQueue(p,records,ex),stats=rosterStats(p,records),person=queued[state.queueOffset%Math.max(1,queued.length)],leave=p.filter(x=>ex[x.id]).length;
 return `${head('Attendance',isManager()?'Verify unresolved attendance within your assigned scope.':'Check in for your own scheduled shift.')}
 <div class="stats">${stat('On roster',stats.scheduled)}${stat('Present',stats.present)}${stat('Absent',stats.absent)}${stat('Needs review',queued.length,leave?`${leave} approved leave`:'Unmarked')}</div>
 <div class="grid two"><section class="panel"><div class="panel-header"><h2>${isManager()?'Manager verification queue':'My attendance'}</h2><span class="pill">${esc(dateLabel(state.date))}</span></div>
 <div class="swipe-area">${isManager()?(person?swipeControls(person):`<div class="empty"><strong>All cards reviewed</strong><p>No unresolved people remain in your assigned scope.</p>${canUndo()?`<button class="button ghost" id="undo-swipe" type="button">Undo last swipe</button>`:''}</div>`):(p[0]?(ex[p[0].id]?`<div class="status-block"><strong>Approved leave</strong><p>Attendance is exempt from the swipe queue.</p></div>`:records[p[0].id]?`<div class="status-block"><h3>Status recorded</h3><p>Marked ${esc(records[p[0].id])}.</p><button class="button" type="button" data-page="profile">Request correction</button></div>`:swipeControls(p[0])):`<div class="empty">No roster assignment</div>`)}</div><p class="form-note">Swipe left for Absent or right for Present. A manager cannot override a submitted status except through a reviewed correction.</p></section>
 <section class="panel"><div class="panel-header"><h2>Shift roster</h2><span class="pill green">${esc(ws().industry)}</span></div><div class="field"><label for="attendance-date">Session date</label><input id="attendance-date" type="date" value="${esc(state.date)}"></div><div class="divider"></div><div class="between"><span class="small-note">Shift</span><strong>${esc(ws().shift)}</strong></div><div class="divider"></div><div class="stack">${p.map(x=>`<div class="person-row">${photo(x)}<div><strong>${esc(x.name)}</strong><small>${esc(x.position)} · ${esc(x.team)}</small></div><span class="pill ${ex[x.id]?'amber':records[x.id]==='present'?'green':records[x.id]==='absent'?'red':''} right">${esc(ex[x.id]?'Approved leave':records[x.id]||'Unmarked')}</span></div>`).join('')}</div></section></div>`;
}
function commitmentsView(){const p=people(),c=commitmentStats(p,currentCommitments()),target=state.targets[state.workspace]||ws().target;return `${head('Attendance commitments','Make next-shift coverage visible before the shift starts.')}<div class="stats">${stat('Confirmed',c.confirmed)}${stat('At risk',c.atRisk)}${stat('Unavailable',c.unavailable)}${stat('No reply',c.pending)}</div><div class="grid two"><section class="panel"><div class="panel-header"><h2>${isManager()?'Team responses':'My next shift'}</h2><span class="pill">${esc(ws().shift)}</span></div>${isManager()?`<div class="stack">${p.map(x=>`<div class="person-row">${photo(x)}<div><strong>${esc(x.name)}</strong><small>${esc(ws().groupLabel)} ${esc(x.team)}</small></div><span class="pill right">${esc(currentCommitments()[x.id]||'No reply')}</span></div>`).join('')}</div>`:`<p class="muted">Update your commitment before the next shift.</p><div class="stack" style="margin-top:20px"><button class="button success full" data-commit="confirmed">✓ Confirmed</button><button class="button full" data-commit="risk">At risk</button><button class="button danger full" data-commit="unavailable">Unavailable</button></div><p class="form-note">Your response: <strong>${esc(currentCommitments()[p[0]?.id]||'Not submitted')}</strong></p>`}</section><section class="panel"><div class="panel-header"><h2>Staffing projection</h2><span class="pill green">Confirmed only</span></div><p class="muted">Counts verified commitments, not speculative attendance probabilities.</p><div style="margin:22px 0"><h1>${projectedCoverage(c)} <span class="muted" style="font-size:18px">/ ${target} required</span></h1><div class="bar-track" style="margin-top:12px;height:12px"><div class="bar-fill" style="width:${Math.min(100,projectedCoverage(c)/target*100)}%"></div></div></div><span class="pill ${projectedCoverage(c)>=target?'green':'amber'}">${projectedCoverage(c)>=target?'Coverage target met':`${Math.max(0,target-projectedCoverage(c))} still to confirm`}</span></section></div>`;}
function reportsView(){
 if(!canManage(actor(),'viewReports'))return `${head('Reports','Manager-only demo view')}<div class="panel empty"><strong>Restricted manager report</strong><p>Select a manager demo identity to preview authorized attendance reports.</p></div>`;
 const p=people(),a=currentAttendance(),ex=currentExceptions(),s=rosterStats(p,a),leave=p.filter(x=>ex[x.id]).length;
 return `${head('Attendance reports','Scoped results for '+actor().title+'.',canManage(actor(),'exportReports')?`<button class="button" id="export-csv" type="button">Export authorized CSV ↓</button>`:'<span class="pill">View only · Level 1</span>')}
 <div class="stats">${stat('Scheduled',s.scheduled)}${stat('Present',s.present)}${stat('Absent',s.absent)}${stat('Unresolved',Math.max(0,s.pending-leave),`${leave} approved leave`)}</div>
 <div class="grid two"><section class="panel"><div class="panel-header"><h2>Attendance distribution</h2><span class="pill">${esc(dateLabel(state.date))}</span></div><div class="bars">${[['Present',s.present,''],['Absent',s.absent,'red'],['Unmarked',Math.max(0,s.pending-leave),'amber'],['Approved leave',leave,'']].map(([n,v,cls])=>`<div class="bar-row"><strong>${n}</strong><div class="bar-track"><div class="bar-fill ${cls}" style="width:${s.scheduled?100*v/s.scheduled:0}%"></div></div><strong>${v}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-header"><h2>Coverage and governance</h2><span class="pill amber">Demo</span></div><p class="small-note">Team leaders see their assigned team. Levels 2–3 can export organization-wide records. Approved leave and unresolved records remain separate from absences.</p></section></div>
 <section class="panel" style="margin-top:18px"><div class="panel-header"><h2>Attendance register</h2><span class="pill">${p.length} in scope</span></div><div class="table-scroll"><table class="table"><thead><tr><th>Name</th><th>Position</th><th>${esc(ws().groupLabel)}</th><th>Date</th><th>Status</th></tr></thead><tbody>${p.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.position)}</td><td>${esc(x.team)}</td><td>${esc(state.date)}</td><td><span class="pill ${ex[x.id]?'amber':a[x.id]==='present'?'green':a[x.id]==='absent'?'red':''}">${esc(ex[x.id]?'Approved leave':a[x.id]||'Unmarked')}</span></td></tr>`).join('')}</tbody></table></div></section>`;
}
function teamView(){const p=people();return `${head('People and teams','See the reporting hierarchy and the people within your demo access scope.')}
 <section class="panel" style="margin-bottom:18px"><div class="panel-header"><h2>Organization hierarchy</h2><span class="pill">4 levels</span></div><div class="grid four"><div class="status-block"><span class="eyebrow">LEVEL 3</span><h3>Site Director</h3><p>Organization oversight</p></div><div class="status-block"><span class="eyebrow">LEVEL 2</span><h3>Operations Manager</h3><p>Multi-team access</p></div><div class="status-block"><span class="eyebrow">LEVEL 1</span><h3>${esc(ws().managerTitle)}</h3><p>Assigned team</p></div><div class="status-block"><span class="eyebrow">MEMBER</span><h3>${esc(ws().personLabel)}</h3><p>Personal attendance</p></div></div></section>
 <section class="panel"><div class="panel-header"><h2>${esc(ws().groupLabel)} roster</h2><span class="pill">${p.length} ${isManager()?'in scope':'visible'}</span></div><div class="grid three">${p.map(x=>`<div class="person-row">${photo(x)}<div><strong>${esc(x.name)}</strong><small>${esc(x.position)}<br>${esc(ws().groupLabel)} ${esc(x.team)}</small></div></div>`).join('')}</div></section>`;}
function updatesView(){const userUpdates=state.announcements.filter(x=>x.workspace===state.workspace&&(actor().level>=2||x.team==='all'||x.team===actor().team)),items=[{id:'a1',text:'Please confirm your next shift early so coverage can be planned.',author:'Operations',scope:'All teams'},{id:'a2',text:'Great job on team collaboration this week.',author:'Team Leader',scope:'Team Orion'},...userUpdates];return `${head('Announcements','Communicate team updates with visible acknowledgement status.')}${canManage(actor(),'publishAnnouncement')?`<section class="panel" style="margin-bottom:18px"><div class="panel-header"><h2>New announcement</h2><span class="pill">${actor().level===1?'Assigned team':'All teams'} · Demo</span></div><div class="field"><label for="new-announcement">Message</label><textarea id="new-announcement" maxlength="700" placeholder="Share a shift update, reminder, or team recognition..."></textarea></div><div style="margin-top:12px"><button class="button primary" id="post-announcement">Post announcement</button></div></section>`:''}<section class="panel"><div class="panel-header"><h2>Team feed</h2><span class="pill">${items.length} updates</span></div>${items.map(x=>`<article class="announcement"><div class="avatar letter">${esc(x.author.slice(0,1))}</div><div style="min-width:0;flex:1"><div class="between"><strong>${esc(x.author)}</strong><span class="pill">${esc(x.scope||'Workspace')}</span></div><p style="margin:8px 0;overflow-wrap:anywhere">${esc(x.text)}</p><button class="button ghost" type="button" data-ack="${esc(x.id)}">${state.acked[x.id]?'✓ Acknowledged':'Acknowledge'}</button></div></article>`).join('')}</section>`;}
function gamesView(){const tabs=[['wheel','Spin the Wheel'],['ducks','Duck Race'],['cards','Pick a Card'],['trivia','Trivia']];return `${head('Play together','A little fun for meetings, class, and team huddles.')}`+`<div class="games-tabs">${tabs.map(([id,label])=>`<button type="button" class="button" aria-pressed="${state.game===id}" data-game="${id}">${label}</button>`).join('')}</div>`+(state.game==='trivia'?triviaView():gameWithEntries());}
function gameWithEntries(){const names=parseEntries(state.gameText);const short=names.length<2;return `<div class="game-shell"><section class="panel game-main"><div class="panel-header"><h2>${state.game==='wheel'?'Spin the Wheel':state.game==='ducks'?'Duck Race':'Pick a Card'}</h2><span class="pill">${names.length} entries</span></div><div class="game-surface">${state.game==='wheel'?wheelView(names):state.game==='ducks'?duckView(names):cardView(names)}</div></section><aside class="panel game-controls"><div class="panel-header"><h2>Participants</h2><button class="button ghost" id="toggle-entries" type="button">${state.entriesHidden?'Show entries':'Hide entries'}</button></div>${state.entriesHidden?`<p class="small-note">The entry editor is hidden. You can still play with the ${names.length} current entries.</p>`:`<div class="field"><label for="game-entries">Names or free text · one per line</label><textarea id="game-entries" maxlength="4500" placeholder="Alex\nJamie\nPat\nTeam A">${esc(state.gameText)}</textarea></div><p class="form-note">Add 2–20 unique entries. No team roster is required.</p><div class="game-presets"><button class="button" id="sample-entries" type="button">Sample entries</button><button class="button ghost" id="clear-entries" type="button">Clear</button></div><div class="divider"></div><div class="entry-list">${names.map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div>`}<div class="divider"></div><button class="button primary full" id="start-game" type="button" ${short||state.gameRunning?'disabled':''}>${state.game==='wheel'?'Spin the wheel':state.game==='ducks'?'Start race':'Shuffle cards'}</button>${short?`<p class="small-note">Enter at least two items to play.</p>`:''}${state.gameWinner!==null?`<div class="status-block"><span class="eyebrow">SELECTED</span><h3>${esc(state.gameWinner)}</h3><p>Would you like to keep the entry for the next round?</p><div class="game-presets" style="margin-top:11px"><button class="button success" id="keep-entry" type="button">Keep</button><button class="button danger" id="remove-entry" type="button">Remove</button></div></div>`:''}</aside></div>`;}
const wheelColors=['#276d54','#d2a55c','#8aa99f','#d37c72','#98a4d6','#77a2a0','#a980ba','#c4bb87','#637c98','#b19e83'];
function slicePath(i,n){const start=-90+i*360/n,end=-90+(i+1)*360/n,rad=a=>a*Math.PI/180;const x1=250+229*Math.cos(rad(start)),y1=250+229*Math.sin(rad(start)),x2=250+229*Math.cos(rad(end)),y2=250+229*Math.sin(rad(end));return `M250 250L${x1.toFixed(3)} ${y1.toFixed(3)}A229 229 0 ${360/n>180?1:0} 1 ${x2.toFixed(3)} ${y2.toFixed(3)}Z`;}
function wheelView(names){if(names.length<2)return `<div class="empty"><strong>Your wheel is ready.</strong><p>Enter two or more names to build your wheel.</p><img src="./brand.svg" width="90" height="90" alt="" style="margin:20px auto"></div>`;return `<div class="wheel-wrap"><span class="wheel-pointer" aria-hidden="true"></span><svg class="wheel-svg" id="wheel" viewBox="0 0 500 500" role="img" aria-label="Prize wheel with ${names.length} entries" style="--angle:${state.wheelRotation}deg">${names.map((x,i)=>{const a=-90+(i+.5)*360/names.length,rad=a*Math.PI/180,r=names.length>12?133:145,cx=250+r*Math.cos(rad),cy=250+r*Math.sin(rad);return `<g><path d="${slicePath(i,names.length)}" fill="${wheelColors[i%wheelColors.length]}" stroke="#fff" stroke-width="2"/><text x="${cx.toFixed(2)}" y="${cy.toFixed(2)}" fill="#fff" font-size="${names.length>14?10:12}" font-weight="750" text-anchor="middle" dominant-baseline="middle" transform="rotate(${(a+90).toFixed(2)} ${cx.toFixed(2)} ${cy.toFixed(2)})">${esc(x.slice(0,names.length>12?12:17))}</text></g>`;}).join('')}</svg><img class="wheel-center" src="./brand.svg" alt="QSwipe logo"></div><div class="game-result" role="status">${state.gameRunning?'<strong>Spinning…</strong>':state.gameWinner?`<span class="eyebrow">WINNER</span><strong>${esc(state.gameWinner)}</strong>`:'<p class="small-note">Spin to pick a participant at random.</p>'}</div>`;}
function duckView(names){return names.length<2?`<div class="empty"><strong>Ready, set, duck!</strong><p>Enter at least two participants to build the racing lanes.</p></div>`:`<div class="race-lanes" id="race-lanes">${names.map((name,i)=>`<div class="racer"><span class="racer-name">${esc(name)}</span><div class="racer-track"><span class="duck" data-duck="${i}" aria-label="Duck representing ${esc(name)}">🦆</span></div></div>`).join('')}</div><div class="game-result" role="status">${state.gameRunning?'<strong>Racing!</strong>':state.gameWinner?`<span class="eyebrow">FIRST PLACE</span><strong>🏆 ${esc(state.gameWinner)}</strong>`:'<p class="small-note">Start a race to see the winner.</p>'}</div>`;}
function cardView(names){if(names.length<2)return `<div class="empty"><strong>Pick a card.</strong><p>Enter participants, then shuffle to make a face-down deck.</p></div>`;const entries=state.cardOrder.length===names.length?state.cardOrder:names;return `<div class="card-grid">${entries.slice(0,9).map((name,i)=>`<button class="flip-card ${state.cardRevealed===i?'revealed':''}" data-flip="${i}" type="button" aria-label="${state.cardRevealed===i?'Revealed card':'Flip card '+(i+1)}" ${state.cardRevealed!==-1?'disabled':''}><span class="flip-card-inner"><span class="flip-face back"><img src="./brand.svg" alt=""><small>QSwipe</small></span><span class="flip-face front"><span class="eyebrow">SELECTED</span><strong>${esc(name)}</strong></span></span></button>`).join('')}</div><p class="small-note">${state.cardRevealed<0?'Tap any face-down card to reveal a name.':'Shuffle again for another round.'}</p>`;}
function triviaView(){const cats=['Mixed','Math',...new Set(FACTS.map(f=>f[0]))];const t=state.trivia;return `<div class="grid two"><section class="panel"><div class="panel-header"><h2>Trivia challenge</h2><span class="pill">${t?'In progress':'Ready'}</span></div>${t?`<div class="trivia-card"><div class="between"><span class="eyebrow">QUESTION ${t.index+1} OF ${t.questions.length}</span><span class="pill green">${t.score} correct</span></div><div class="trivia-progress" style="margin:12px 0 18px"><div style="width:${100*(t.index+1)/t.questions.length}%"></div></div><span class="pill">${esc(t.questions[t.index].category)}</span><h2>${esc(t.questions[t.index].question)}</h2><div class="trivia-options">${t.questions[t.index].options.map((opt,i)=>`<button class="trivia-option ${t.selected!==null?(i===t.questions[t.index].answer?'correct':i===t.selected?'wrong':''):''}" data-answer="${i}" type="button" ${t.selected!==null?'disabled':''}>${esc(opt)}</button>`).join('')}</div>${t.selected!==null?`<p class="form-note">${t.selected===t.questions[t.index].answer?'Correct!':'Good try!'} The answer is ${esc(t.questions[t.index].options[t.questions[t.index].answer])}.</p><button class="button primary" id="next-question" style="margin-top:12px" type="button">${t.index+1===t.questions.length?'See results':'Next question →'}</button>`:''}</div>`:`<div class="empty"><strong>Millions of possible math challenges.</strong><p>Plus a starter factual question set. Select a topic and play a short round.</p></div>`}</section><aside class="panel"><div class="panel-header"><h2>Quiz settings</h2><span class="pill">Solo or team</span></div><div class="stack"><div class="field"><label for="trivia-category">Category</label><select id="trivia-category">${cats.map(c=>`<option ${state.triviaCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="trivia-length">Questions per round</label><select id="trivia-length">${[5,10,15].map(n=>`<option value="${n}" ${state.triviaLength===n?'selected':''}>${n}</option>`).join('')}</select></div><button class="button primary full" id="start-trivia" type="button">${t?'Restart round':'Start trivia'}</button>${t?`<button class="button ghost full" id="stop-trivia">End round</button>`:''}</div><div class="divider"></div><p class="small-note">The math generator produces many unique combinations, but generated challenges should not be confused with millions of fact-checked trivia questions.</p></aside></div>`;}
function bindView(){all('[data-page]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page;state.queueOffset=0;clearGameTimer();render();window.scrollTo({top:0,behavior:'instant'});}));$('#go-attendance')?.addEventListener('click',()=>{state.page='attendance';render();});$('#attendance-date')?.addEventListener('change',e=>{if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)){state.date=e.target.value;state.queueOffset=0;render();}});$('#reset-demo')?.addEventListener('click',()=>{notify('Use a reviewed correction to change attendance.');});all('[data-commit]').forEach(b=>b.addEventListener('click',()=>{if(isManager())return;const key=currentKey(),member=people()[0];if(!member)return;state.commitments[key]??={};state.commitments[key][member.id]=b.dataset.commit;save();notify('Commitment updated in this browser');render();}));const card=$('#swipe-card');if(card)bindSwipe(card);$('#mark-present')?.addEventListener('click',()=>markAttendance('present'));$('#mark-absent')?.addEventListener('click',()=>markAttendance('absent'));$('#skip-card')?.addEventListener('click',()=>{if(!isManager())return;state.queueOffset++;render();});$('#undo-swipe')?.addEventListener('click',undoAttendance);$('#export-csv')?.addEventListener('click',exportCSV);$('#post-announcement')?.addEventListener('click',postAnnouncement);all('[data-ack]').forEach(b=>b.addEventListener('click',()=>{state.acked[b.dataset.ack]=true;save();render();}));all('[data-game]').forEach(b=>b.addEventListener('click',()=>{state.game=b.dataset.game;resetGameResult();render();}));$('#toggle-entries')?.addEventListener('click',()=>{state.entriesHidden=!state.entriesHidden;render();});$('#sample-entries')?.addEventListener('click',()=>{state.gameText='Alex\nJamie\nPat\nTaylor\nMorgan\nSam';resetGameResult();render();});$('#clear-entries')?.addEventListener('click',()=>{state.gameText='';resetGameResult();render();});$('#game-entries')?.addEventListener('input',e=>{const a=e.target.selectionStart;state.gameText=e.target.value;resetGameResult();render();const box=$('#game-entries');if(box){box.focus();box.setSelectionRange(a,a);}});$('#start-game')?.addEventListener('click',startGame);$('#keep-entry')?.addEventListener('click',()=>{resetGameResult();render();});$('#remove-entry')?.addEventListener('click',()=>{const chosen=state.gameWinner;state.gameText=parseEntries(state.gameText).filter(x=>x!==chosen).join('\n');resetGameResult();render();});all('[data-flip]').forEach(b=>b.addEventListener('click',()=>{if(state.cardRevealed>=0)return;state.cardRevealed=Number(b.dataset.flip);state.gameWinner=state.cardOrder[state.cardRevealed];render();}));$('#trivia-category')?.addEventListener('change',e=>state.triviaCategory=e.target.value);$('#trivia-length')?.addEventListener('change',e=>state.triviaLength=Number(e.target.value));$('#start-trivia')?.addEventListener('click',startTrivia);$('#stop-trivia')?.addEventListener('click',()=>{state.trivia=null;render();});all('[data-answer]').forEach(b=>b.addEventListener('click',()=>{const t=state.trivia;if(!t||t.selected!==null)return;t.selected=Number(b.dataset.answer);if(t.selected===t.questions[t.index].answer)t.score++;render();}));$('#next-question')?.addEventListener('click',()=>{const t=state.trivia;if(!t)return;if(t.index===t.questions.length-1){const score=t.score;const len=t.questions.length;state.trivia=null;notify(`Round complete: ${score}/${len} correct`);}else{t.index++;t.selected=null;}render();});bindManagement();}
/** Manager and profile pages. These permissions are illustrative, never a security boundary. */
function managerView(){
  if(!isManager())return `${head('Manager workspace','Manager preview only')}<section class="panel empty">Switch to a manager preview role.</section>`;
  const current=people(),filter=state.managerTeamFilter;
  const p=filter==='all'?current:current.filter(x=>x.team===filter);
  const a=currentAttendance(),exceptions=currentExceptions(),summary=rosterStats(p,a),outstanding=countQueue(p,a,exceptions);
  const requests=state.requests.filter(r=>r.workspace===state.workspace&&r.date===state.date&&canReviewRequest(actor(),r,allWorkspacePeople())&&p.some(x=>x.id===r.personId));
  const c=commitmentStats(p,currentCommitments()),target=state.targets[state.workspace]||ws().target;
  const allTeams=[...new Set(current.map(x=>x.team))];
  return `${head('Manager workspace',`Level ${actor().level} · ${actor().title} · ${actor().level===1?'Assigned team only':'Organization scope'}`,`<button class="button primary" data-page="attendance" type="button">Review swipe queue</button>`)}
  <div class="demo-banner"><strong>Demo permissions only.</strong> These controls are interactive in your browser, not authenticated, shared or secure. Do not use real personnel records.</div>
  <section class="panel manager-controls"><div class="field"><label for="manager-date">Attendance date</label><input id="manager-date" type="date" value="${esc(state.date)}"></div><div class="field"><label for="manager-team-filter">Team / class</label><select id="manager-team-filter"><option value="all">All in my scope</option>${allTeams.map(t=>`<option value="${esc(t)}" ${t===filter?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Current access</label><div class="role-summary">${esc(actor().level===1?'Only '+actor().team:'All assigned teams')}</div></div></section>
  <div class="stats">${stat('Roster',p.length)}${stat('Present',summary.present)}${stat('Needs verification',outstanding.length)}${stat('Pending approvals',requests.length)}</div>
  <div class="grid two"><section class="panel"><div class="panel-header"><h2>Approval inbox</h2><span class="pill ${requests.length?'amber':'green'}">${requests.length} pending</span></div>
  ${requests.length?`<div class="stack">${requests.map(r=>{const person=allWorkspacePeople().find(x=>x.id===r.personId);return `<article class="approval-item"><div class="between"><strong>${esc(person?.name||'Team member')}</strong><span class="pill">${esc(r.type==='leave'?'Leave request':'Attendance correction')}</span></div><p class="small-note">${esc(person?.team||'')} · ${esc(dateLabel(r.date))}${r.type==='correction'?` · Requested ${esc(r.desiredStatus)}`:''}</p><p class="approval-note">${esc(r.note)}</p><div class="button-pair"><button class="button success" type="button" data-request-id="${esc(r.id)}" data-review="approved">Approve</button><button class="button danger" type="button" data-request-id="${esc(r.id)}" data-review="declined">Decline</button></div></article>`;}).join('')}</div>`:`<div class="empty"><strong>All clear</strong><p>No pending requests for this date and scope.</p></div>`}
  </section><section class="panel"><div class="panel-header"><h2>Staffing and attendance</h2><span class="pill green">${esc(ws().shift)}</span></div><div class="between"><span class="small-note">Confirmed for next shift</span><strong>${c.confirmed} / ${target} target</strong></div><div class="bar-track" style="margin-top:12px;height:12px"><div class="bar-fill" style="width:${Math.min(100,c.confirmed/target*100)}%"></div></div><div class="divider"></div><div class="bars">${[['Present',summary.present,''],['Absent',summary.absent,'red'],['Unverified',outstanding.length,'amber']].map(([label,n,color])=>`<div class="bar-row"><strong>${label}</strong><div class="bar-track"><div class="bar-fill ${color}" style="width:${p.length?100*n/p.length:0}%"></div></div><strong>${n}</strong></div>`).join('')}</div><p class="form-note">Approved leave: ${p.filter(x=>exceptions[x.id]).length}. Unverified is not a finalized absence.</p><div class="button-pair"><button class="button" type="button" data-page="reports">View reports</button><button class="button" type="button" data-page="commitments">View commitments</button></div></section></div>
  <div class="grid two" style="margin-top:18px"><section class="panel"><div class="panel-header"><h2>Team management</h2><span class="pill">${canManage(actor(),'reassignTeam')?'Level 2+':'View only'}</span></div>
  ${canManage(actor(),'reassignTeam')?`<p class="small-note">Reassign a sample employee between teams. Changes appear across the demo roster and manager scope.</p><form id="assignment-form" class="stack"><div class="field"><label for="assignment-person">Employee</label><select id="assignment-person">${current.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.team)}</option>`).join('')}</select></div><div class="field"><label for="assignment-team">New team</label><select id="assignment-team">${WORKSPACE_TEAMS[state.workspace].map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select></div><button class="button primary" type="submit">Save team assignment</button></form>`:`<p class="small-note">You can review and verify your ${esc(actor().team)} team. Team transfers are restricted to Level 2 and Level 3 manager previews.</p>`}
  <div class="divider"></div><div class="stack">${p.map(x=>`<div class="person-row">${photo(x)}<div><strong>${esc(x.name)}</strong><small>${esc(x.team)} · ${esc(x.position)}</small></div><span class="pill right">${esc(exceptions[x.id]?'On leave':a[x.id]||'Unmarked')}</span></div>`).join('')}</div></section>
  <section class="panel"><div class="panel-header"><h2>Access and oversight</h2><span class="pill">Level ${actor().level}</span></div>
  <div class="access-matrix">${[['Review assigned attendance',1],['Approve leave and corrections',1],['Post team announcements',1],['Export attendance CSV',2],['Reassign people between teams',2],['View audit activity',2],['Set organization staffing target',3]].map(([title,level])=>`<div class="between access-row"><span>${esc(title)}</span><span class="pill ${actor().level>=level?'green':'amber'}">${actor().level>=level?'Available':`Level ${level}+`}</span></div>`).join('')}</div>
  ${canManage(actor(),'setCoverageTarget')?`<div class="divider"></div><form class="inline-fields" id="target-form"><div class="field"><label for="target-count">Staffing target</label><input id="target-count" type="number" min="1" max="1000" value="${target}"></div><button class="button primary" type="submit">Update target</button></form>`:''}
  ${canManage(actor(),'viewAudit')?`<div class="divider"></div><h3>Recent demo activity</h3><div class="audit-list">${state.audit.filter(x=>x.workspace===state.workspace&&(x.personId===''||!x.personId||allWorkspacePeople().some(p=>p.id===x.personId&&isInScope(actor(),p)))).slice(0,8).map(x=>`<div class="audit-row"><strong>${esc(x.action)}</strong><small>${esc(x.actor)} · ${esc(new Date(x.at).toLocaleString('en-PH'))}</small><span>${esc(x.detail)}</span></div>`).join('')||'<p class="small-note">No recorded actions yet.</p>'}</div>`:''}
  </section></div>`;
}

function profileView(){
 const current=actor(),prefs=state.profiles[state.actorId]||{},mine=allWorkspacePeople().find(x=>x.id===current.memberId),avatar=state.avatarUrls[state.actorId]||(mine?PORTRAITS[mine.portrait]:PORTRAITS[1]);
 const ownRequests=state.requests.filter(x=>x.workspace===state.workspace&&x.personId===current.memberId);
 return `${head('My profile','Personal details, workspace membership and attendance requests.')}
 <div class="grid two"><section class="panel"><div class="panel-header"><h2>Profile details</h2><span class="pill ${isManager()?'green':''}">${isManager()?'Manager · Level '+current.level:'Member'}</span></div>
 <div class="profile-hero"><img src="${esc(avatar)}" class="profile-portrait" alt="Profile preview"><div><h2>${esc(current.name)}</h2><p class="muted">${esc(current.title)}</p><span class="pill">${esc(ws().name)}</span></div></div>
 <form id="profile-form" class="stack"><div class="field"><label for="profile-name">Display name</label><input id="profile-name" maxlength="60" required value="${esc(current.name)}" autocomplete="off"></div><div class="field"><label for="profile-title">Position / title</label><input id="profile-title" maxlength="80" required value="${esc(current.title)}" autocomplete="off"></div><div class="field"><label for="profile-about">About</label><textarea id="profile-about" maxlength="240" rows="3" placeholder="An optional short introduction">${esc(prefs.about||'')}</textarea></div><div class="field"><label for="profile-picture">Profile picture (JPG, PNG or WebP · max 2 MB)</label><input id="profile-picture" type="file" accept="image/jpeg,image/png,image/webp"><span class="form-note">Image stays in this browser tab and is not uploaded or saved to an account.</span></div><button class="button primary" type="submit">Save profile</button></form>
 </section><section class="panel"><div class="panel-header"><h2>Workspace and access</h2><span class="pill">${esc(ws().industry)}</span></div><div class="profile-facts"><div class="between"><span>Workspace</span><strong>${esc(ws().name)}</strong></div><div class="between"><span>Access preview</span><strong>${esc(current.level?`Level ${current.level} manager`:'Member')}</strong></div><div class="between"><span>${esc(ws().groupLabel)}</span><strong>${esc(mine?.team||current.team||'All assigned teams')}</strong></div><div class="between"><span>Shift</span><strong>${esc(ws().shift)}</strong></div></div><div class="divider"></div><h3>Reporting line</h3><div class="manager-chain"><span>Member</span><span>→</span><span>${esc(ws().managerTitle)}</span><span>→</span><span>Level 2</span><span>→</span><span>Level 3</span></div><p class="form-note">The “View as” dropdown changes the demo identity only. It is not login, authorization or a real account role.</p></section></div>
 ${!isManager()?`<section class="panel" style="margin-top:18px"><div class="panel-header"><h2>Attendance and leave requests</h2><span class="pill">Manager review</span></div><p class="small-note">Request an attendance correction or leave review. A manager in your team can approve or decline it in the demo inbox.</p><form id="request-form" class="request-form"><div class="field"><label for="request-type">Request</label><select id="request-type"><option value="correction">Attendance correction</option><option value="leave">Leave review</option></select></div><div class="field"><label for="request-status">Correct status</label><select id="request-status"><option value="present">Present</option><option value="absent">Absent</option></select></div><div class="field request-note"><label for="request-note">Reason</label><textarea id="request-note" required maxlength="300" placeholder="Describe what happened. Avoid sensitive information."></textarea></div><button class="button primary" type="submit">Submit request</button></form><div class="divider"></div><h3>My requests</h3>${ownRequests.length?`<div class="stack">${ownRequests.slice(0,10).map(x=>`<div class="between request-history"><div><strong>${esc(x.type==='leave'?'Leave review':'Attendance correction')}</strong><small>${esc(x.date)} · ${esc(x.note)}</small></div><span class="pill ${x.status==='approved'?'green':x.status==='declined'?'red':'amber'}">${esc(x.status)}</span></div>`).join('')}</div>`:'<p class="small-note">No requests yet.</p>'}</section>`:''}`;
}

function bindManagement(){
 $('#manager-team-filter')?.addEventListener('change',e=>{state.managerTeamFilter=e.target.value;render();});
 $('#manager-date')?.addEventListener('change',e=>{if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)){state.date=e.target.value;state.queueOffset=0;render();}});
 all('[data-review]').forEach(button=>button.addEventListener('click',()=>{
   const request=state.requests.find(r=>r.id===button.dataset.requestId);
   if(!request||!canReviewRequest(actor(),request,allWorkspacePeople())||request.workspace!==state.workspace){notify('Request is no longer available in your scope.');return;}
   const verdict=button.dataset.review;if(!['approved','declined'].includes(verdict))return;
   if(verdict==='approved'){
     const key=`${request.workspace}|${request.date}`;
     if(request.type==='correction'){
       if(!['present','absent'].includes(request.desiredStatus)){notify('Invalid status requested.');return;}
       state.attendance[key]??={};state.attendance[key][request.personId]=request.desiredStatus;
       if(state.exceptions[key])delete state.exceptions[key][request.personId];
     } else if(request.type==='leave'){
       if(state.attendance[key]?.[request.personId]){notify('Existing attendance needs a correction before leave approval.');return;}
       state.exceptions[key]??={};state.exceptions[key][request.personId]={type:'leave',reviewedBy:actor().name};
     } else return;
   }
   request.status=verdict;request.reviewedBy=actor().name;request.reviewedAt=new Date().toISOString();
   auditAction('Request '+verdict,request.personId,request.type+` · ${request.date}`);save();notify('Request '+verdict+' in this demo');render();
 }));
 $('#assignment-form')?.addEventListener('submit',e=>{
   e.preventDefault();const person=allWorkspacePeople().find(p=>p.id===$('#assignment-person')?.value),nextTeam=$('#assignment-team')?.value;
   if(!canReassignPerson(actor(),person,nextTeam,allWorkspacePeople(),WORKSPACE_TEAMS[state.workspace])){notify('Assignment not permitted or unchanged.');return;}
   state.assignments[state.workspace]??={};const prior=person.team;state.assignments[state.workspace][person.id]=nextTeam;
   auditAction('Team reassignment',person.id,`${prior} → ${nextTeam}`);save();notify(person.name+' moved to '+nextTeam);render();
 });
 $('#target-form')?.addEventListener('submit',e=>{
   e.preventDefault();const value=Number($('#target-count')?.value);
   if(!canManage(actor(),'setCoverageTarget')||!Number.isInteger(value)||value<1||value>1000){notify('Not authorized or invalid target.');return;}
   state.targets[state.workspace]=value;auditAction('Coverage target','',String(value));save();notify('Target updated in demo');render();
 });
 $('#profile-form')?.addEventListener('submit',e=>{
   e.preventDefault();const parsed=validateProfile({name:$('#profile-name')?.value,title:$('#profile-title')?.value,about:$('#profile-about')?.value});
   if(parsed.error){notify(parsed.error);return;}
   state.profiles[state.actorId]=parsed.value;save();notify('Profile changes saved in this browser');render();
 });
 $('#profile-picture')?.addEventListener('change',e=>{
   const file=e.target.files?.[0];if(!file)return;
   if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024||file.size===0){notify('Use a JPG, PNG or WebP image under 2 MB.');e.target.value='';return;}
   if(state.avatarUrls[state.actorId])URL.revokeObjectURL(state.avatarUrls[state.actorId]);
   state.avatarUrls[state.actorId]=URL.createObjectURL(file);notify('Photo preview updated for this browser tab');render();
 });
 $('#request-form')?.addEventListener('submit',e=>{
   e.preventDefault();const person=allWorkspacePeople().find(p=>p.id===actor().memberId);
   if(isManager()||!person||!isInScope(actor(),person))return;
   const type=$('#request-type')?.value,note=$('#request-note')?.value?.trim(),desiredStatus=$('#request-status')?.value;
   if(!['correction','leave'].includes(type)||!note||note.length>300){notify('Enter a short reason (up to 300 characters).');return;}
   if(type==='correction'&&(!['present','absent'].includes(desiredStatus)||!currentAttendance()[person.id])){notify('Record attendance first before requesting a correction.');return;}
   if(state.requests.some(r=>r.workspace===state.workspace&&r.date===state.date&&r.personId===person.id&&r.type===type&&r.status==='pending')){notify('A request of this type is already pending.');return;}
   state.requests.unshift({id:crypto.randomUUID(),workspace:state.workspace,date:state.date,personId:person.id,type,note,desiredStatus:type==='correction'?desiredStatus:'',status:'pending',createdAt:new Date().toISOString()});
   auditAction('Request submitted',person.id,type);save();notify('Request sent to demo manager inbox');render();
 });
}

function activePerson(){const p=attendancePeople(),q=countQueue(p,currentAttendance(),currentExceptions());return isManager()?q[state.queueOffset%Math.max(1,q.length)]:p[0];}
function markAttendance(status){
 if(!['present','absent'].includes(status))return;
 const p=activePerson();if(!p)return;const records=currentAttendance();
 if(isManager()&&!canMarkPerson(actor(),p,records,currentExceptions())){notify('Not authorized or record already resolved.');render();return;}
 if(!isManager()&&(p.id!==actor().memberId||records[p.id]||currentExceptions()[p.id])){notify('Use the correction or leave request flow.');return;}
 const key=currentKey(),prev=records[p.id]||null;state.attendance[key]??={};state.attendance[key][p.id]=status;
 state.lastAction={key,id:p.id,prev,at:Date.now()};state.queueOffset=0;auditAction('Attendance check-in',p.id,`${status} · ${state.date}`);save();
 notify(`${p.name} marked ${status}. Undo within 10 seconds.`);render();
}
function undoAttendance(){const a=state.lastAction;if(!canUndo()){notify('Undo expired. Request a correction.');return;}const person=allWorkspacePeople().find(x=>x.id===a.id);if(!isInScope(actor(),person)){notify('This person is no longer in your scope.');return;}if(a.prev)state.attendance[a.key][a.id]=a.prev;else delete state.attendance[a.key][a.id];state.lastAction=null;auditAction('Attendance undo',a.id,'Reversed last swipe');save();notify('Last attendance change undone.');render();}
function bindSwipe(card){let start=null;card.addEventListener('pointerdown',e=>{if(e.button!==0)return;start={x:e.clientX,y:e.clientY};card.classList.add('dragging');});card.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>Math.abs(dy)*1.4){const limited=Math.max(-130,Math.min(130,dx));card.style.setProperty('--tx',`${limited}px`);card.style.setProperty('--rot',`${limited/25}deg`);}});function end(e){if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;card.classList.remove('dragging');card.style.removeProperty('--tx');card.style.removeProperty('--rot');start=null;if(Math.abs(dx)>75&&Math.abs(dx)>Math.abs(dy)*1.4)markAttendance(dx>0?'present':'absent');}card.addEventListener('pointerup',end);card.addEventListener('pointercancel',()=>{start=null;card.classList.remove('dragging');card.style.removeProperty('--tx');card.style.removeProperty('--rot');});card.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();markAttendance(e.key==='ArrowRight'?'present':'absent');}});}
function exportCSV(){if(!canManage(actor(),'exportReports')){notify('Export requires Level 2 or Level 3 manager preview.');return;}const rows=[['Name','Position','Team or class','Date','Status'],...people().map(p=>[p.name,p.position,p.team,state.date,currentExceptions()[p.id]?'Approved leave':currentAttendance()[p.id]||'Unmarked'])];const csv=rows.map(row=>row.map(value=>`"${String(value).replace(/^([=+\-@\t\r])/,'\'$1').replaceAll('"','""')}"`).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`qswipe-attendance-${state.date}.csv`;link.click();URL.revokeObjectURL(url);auditAction('Report export','',`${rows.length-1} rows`);save();notify('Scoped CSV exported from demo records');}
function postAnnouncement(){if(!canManage(actor(),'publishAnnouncement')){notify('Manager access required.');return;}const text=$('#new-announcement')?.value?.trim();if(!text){notify('Write an announcement first.');return;}state.announcements.unshift({id:'u'+Date.now(),author:actor().name,scope:actor().level===1?'Team '+actor().team:ws().name,team:actor().level===1?actor().team:'all',text:text.slice(0,700),workspace:state.workspace});auditAction('Announcement','',`${actor().level===1?'Team '+actor().team:'All teams'}`);save();render();notify('Announcement saved locally.');}
function startGame(){const entries=parseEntries(state.gameText);if(entries.length<2||state.gameRunning)return;state.gameWinner=null;state.cardRevealed=-1;if(state.game==='cards'){const pool=[...entries];for(let i=pool.length-1;i>0;i--){const j=rollIndex(i+1);[pool[i],pool[j]]=[pool[j],pool[i]];}state.cardOrder=pool;render();return;}const selected=rollIndex(entries.length);state.gameRunning=true;render();if(state.game==='wheel'){const degrees=360/entries.length;const landing=(360-(selected+.5)*degrees)%360;const anchor=Math.ceil(state.wheelRotation/360)*360;state.wheelRotation=anchor+360*6+landing;const wheel=$('#wheel');requestAnimationFrame(()=>{if(wheel){wheel.style.setProperty('--angle',`${state.wheelRotation}deg`);}});gameTimer=setTimeout(()=>{state.gameWinner=entries[selected];state.gameRunning=false;render();},window.matchMedia('(prefers-reduced-motion: reduce)').matches?50:4500);}else{const duration=window.matchMedia('(prefers-reduced-motion: reduce)').matches?50:3100;requestAnimationFrame(()=>{all('[data-duck]').forEach((duck,i)=>{const track=duck.closest('.racer-track');const width=Math.max(0,track.clientWidth-duck.clientWidth-15);duck.style.setProperty('--speed',`${duration/1000}s`);duck.style.setProperty('--move',`${Math.round(width*(i===selected?1:0.68+(rollIndex(22)/100)))}px`);});});gameTimer=setTimeout(()=>{state.gameWinner=entries[selected];state.gameRunning=false;render();},duration+120);}}
function startTrivia(){const len=state.triviaLength;const questions=[],used=new Set();let n=0;while(questions.length<len&&n<300){const seed=rollIndex(4_000_000)+n*29;const q=triviaQuestion(seed,state.triviaCategory);n++;const key=q.question;if(used.has(key))continue;used.add(key);questions.push(q);}state.trivia={questions,index:0,selected:null,score:0};render();}
$('#workspace').addEventListener('change',e=>{if(!WORKSPACES[e.target.value])return;state.workspace=e.target.value;state.managerTeamFilter='all';state.queueOffset=0;state.lastAction=null;resetGameResult();render();});
$('#role').addEventListener('change',e=>{if(!DEMO_ACTORS[e.target.value])return;state.actorId=e.target.value;state.role=isManager()?'manager':'member';state.queueOffset=0;state.lastAction=null;render();});
$('#profile-shortcut')?.addEventListener('click',()=>{state.page='profile';render();});
render();
